import { writeOutput } from "./codegen";

const DOCS_URL = "https://render.com/docs/api";
const PLACEHOLDER_VALUE = "rnd_c0ffee5afe10ca1c0ffee5afe10ca1c0ffee5afe10ca1";

function generateTypeScript(): string {
  const lines: string[] = [
    "// Auto-generated from Render API docs.",
    `// Source: ${DOCS_URL}`,
    "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:render",
    "//",
    "// DO NOT EDIT THIS FILE MANUALLY.",
    "",
    'import type { FirewallConfig } from "../firewall-types";',
    "",
    "export const renderFirewall = {",
    '  name: "render",',
    '  description: "Render public API",',
    "  placeholders: {",
    `    RENDER_API_KEY: "${PLACEHOLDER_VALUE}",`,
    "  },",
    "  apis: [",
    "    {",
    '      base: "https://api.render.com/v1",',
    "      auth: {",
    "        headers: {",
    '          Authorization: "Bearer ${{ secrets.RENDER_API_KEY }}",',
    "        },",
    "      },",
    "      permissions: [],",
    "    },",
    "  ],",
    "} as const satisfies FirewallConfig;",
    "",
  ];
  return lines.join("\n");
}

export async function generate(): Promise<void> {
  console.error("Generating Render firewall config...");
  const ts = generateTypeScript();
  writeOutput("render", ts, import.meta.dirname);
}
